// Extrai dados do HTML usando regex
const html = $input.item.json.data || '';
const url = $('Webhook').item.json.body.url || $('Webhook').item.json.url;

// Extrai title
const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
const ogTitleMatch = html.match(/<meta[^>]*property=["']og:title["'][^>]*content=["']([^"']+)["']/i);
const h1Match = html.match(/<h1[^>]*>([^<]+)<\/h1>/i);

const title = (titleMatch && titleMatch[1]) ||
              (ogTitleMatch && ogTitleMatch[1]) ||
              (h1Match && h1Match[1]) ||
              'Sem título';

// Conta imagens
const imgMatches = html.match(/<img[^>]*>/gi) || [];
const num_images = imgMatches.length;

// Conta vídeos
const videoMatches = html.match(/<video[^>]*>/gi) || [];
const iframeYoutubeMatches = html.match(/<iframe[^>]*youtube[^>]*>/gi) || [];
const iframeVimeoMatches = html.match(/<iframe[^>]*vimeo[^>]*>/gi) || [];
const num_videos = videoMatches.length + iframeYoutubeMatches.length + iframeVimeoMatches.length;

// Conta links
const linkMatches = html.match(/<a[^>]*href=["']([^"']+)["'][^>]*>/gi) || [];

let num_links_internal = 0;
let num_links_external = 0;

const baseDomain = new URL(url).hostname;

for (const link of linkMatches) {
  const hrefMatch = link.match(/href=["']([^"']+)["']/i);
  if (!hrefMatch) continue;

  const href = hrefMatch[1];

  if (href.startsWith('/') || href.startsWith('#')) {
    num_links_internal++;
  } else if (href.startsWith('http')) {
    try {
      const linkDomain = new URL(href).hostname;
      if (linkDomain === baseDomain) {
        num_links_internal++;
      } else {
        num_links_external++;
      }
    } catch (e) {
      // Link inválido, ignora
    }
  }
}

// Remove tags HTML e pega preview do texto
const textOnly = html.replace(/<script[^>]*>.*?<\/script>/gi, '')
                     .replace(/<style[^>]*>.*?<\/style>/gi, '')
                     .replace(/<[^>]+>/g, ' ')
                     .replace(/\s+/g, ' ')
                     .trim();

const text_preview = textOnly.slice(0, 500);

return {
  url: url,
  title: title.trim(),
  num_images: num_images,
  num_videos: num_videos,
  num_links_internal: num_links_internal,
  num_links_external: num_links_external,
  text_preview: text_preview,
  html_size: html.length,
  success: true
};
